sp_widget.client_script:
api.controller = function($scope, $location, spUtil) {
  var c = this;

  // Background image: use widget option if set, else fallback
  c.backgroundImage = c.options.background_image ||
    '/sp?id=attachment&table=sp_widget&sys_id=' + c.data.widgetSysId;

  c.startNewApplication = function() {
    // Navigate to your “new grant application” page
    $location.url('/sp?id=grant_new_application');
  };

  c.browseOpportunities = function() {
    // Navigate to opportunity listing
    $location.url('/sp?id=grant_opportunity_catalog');
  };

  c.viewGuides = function() {
    // Navigate to guides / knowledge page
    $location.url('/sp?id=grant_applicant_guides');
  };
}

sp_widget.css:
.grants-hero-banner {
  position: relative;
  padding: 80px 0 90px 0;
  color: #ffffff;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.grants-hero-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(5, 30, 70, 0.92), rgba(3, 80, 130, 0.80));
}

.grants-hero-content {
  position: relative;
  z-index: 1;
}

.grants-hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 15px;
}

.grants-hero-title span {
  color: #ffd66b;
}

.grants-hero-subtitle {
  font-size: 1.05rem;
  max-width: 620px;
  margin-bottom: 20px;
  line-height: 1.6;
}

.grants-hero-benefits li {
  margin-bottom: 6px;
  font-size: 0.98rem;
}

.grants-hero-benefits i {
  margin-right: 8px;
  color: #ffd66b;
}

.grants-hero-actions {
  margin-top: 20px;
  margin-bottom: 12px;
}

.grants-hero-actions .btn-primary {
  background-color: #ffb52c;
  border-color: #ffb52c;
  color: #062445;
}

.grants-hero-actions .btn-primary:hover {
  background-color: #ffca5d;
  border-color: #ffca5d;
}

.grants-hero-secondary {
  color: #ffffff;
  text-decoration: underline;
}

.grants-hero-trust {
  font-size: 0.85rem;
  opacity: 0.85;
}

.grants-hero-side-panel {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.grants-hero-card {
  background: rgba(4, 27, 60, 0.9);
  border-radius: 12px;
  padding: 20px 22px;
  max-width: 320px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
}

.grants-hero-card h3 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.grants-hero-card ol {
  padding-left: 18px;
  margin-bottom: 10px;
}

.grants-hero-card li {
  font-size: 0.92rem;
  margin-bottom: 4px;
}

.grants-hero-link {
  font-size: 0.9rem;
  color: #ffd66b;
  cursor: pointer;
}

@media (max-width: 767px) {
  .grants-hero-banner {
    padding: 50px 0 60px 0;
    text-align: left;
  }
  .grants-hero-side-panel {
    justify-content: flex-start;
    margin-top: 25px;
  }
}

sp_widget.script:
(function () {
  function optVal(opt, fallback) {
    if (!opt)
      return fallback || "";
    if (typeof opt === "string")
      return opt;
    if (opt.value)
      return opt.value;
    return fallback || "";
  }

  // Background image from db_image
  var bgId = optVal(options.background_image);
  if (bgId) {
    var image_gr = new GlideRecordSecure("db_image");
    if (image_gr.get(bgId)) {
      options.background_image = encodeURIComponent(image_gr.name);
    } else {
      options.background_image = "";
    }
  } else {
    options.background_image = "";
  }

  // Heading and description from JSON options
  var rawHeading = optVal(
    options.heading,
    "Powering America's Grant Innovation"
  );
  data.heading = rawHeading;

  var rawDesc = optVal(
    options.description,
    "Discover, apply for, and track federal grant opportunities that advance infrastructure, safety, and community impact."
  );
  data.description = rawDesc;

  // Alignment (fallback to left)
  options.alignment = optVal(options.alignment, "left");

  // Static badge
  data.badge = "Federal Grant Opportunities";
})();
